module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  function integer clog2;
    input integer value;
    integer i;
    begin
      clog2 = 0;
      for (i = value - 1; i > 0; i = i >> 1)
        clog2 = clog2 + 1;
    end
  endfunction

  localparam ADDR = clog2(DEPTH);

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [ADDR:0]    wr_ptr;
  reg [ADDR:0]    rd_ptr;

  wire [ADDR-1:0] wr_addr = wr_ptr[ADDR-1:0];
  wire [ADDR-1:0] rd_addr = rd_ptr[ADDR-1:0];

  assign full  = (wr_ptr[ADDR] != rd_ptr[ADDR]) &&
                 (wr_ptr[ADDR-1:0] == rd_ptr[ADDR-1:0]);
  assign empty = (wr_ptr == rd_ptr);

  wire do_wr = wr_en && !full;
  wire do_rd = rd_en && !empty;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr <= {(ADDR+1){1'b0}};
      rd_ptr <= {(ADDR+1){1'b0}};
      dout   <= {WIDTH{1'b0}};
    end else begin
      if (do_wr) begin
        mem[wr_addr] <= din;
        wr_ptr       <= wr_ptr + 1'b1;
      end
      if (do_rd) begin
        dout   <= mem[rd_addr];
        rd_ptr <= rd_ptr + 1'b1;
      end
    end
  end

endmodule

